import numpy as np

def select_next_node(current_node: int, depot: int, unvisited_nodes: np.ndarray, rest_capacity: float, current_time: float,
                        demands: np.ndarray, distance_matrix: np.ndarray, time_windows: np.ndarray) -> int:

    if len(unvisited_nodes) == 0:
        if current_node != depot:
            return depot
        return int(unvisited_nodes[0])

    # Filter candidates by capacity and time-window feasibility
    candidates = []
    for node in unvisited_nodes:
        node = int(node)
        demand = float(demands[node])
        if demand > rest_capacity:
            continue
        dist = float(distance_matrix[current_node][node])
        arrive = current_time + dist
        tw_start, tw_end = float(time_windows[node][0]), float(time_windows[node][1])
        if arrive > tw_end:
            continue
        candidates.append((node, demand, dist, arrive, tw_start, tw_end))

    if len(candidates) == 0:
        if current_node != depot:
            return depot
        return int(unvisited_nodes[0])

    if len(candidates) == 1:
        return int(candidates[0][0])

    # Normalize helpers
    max_dist = max(c[2] for c in candidates)
    if max_dist <= 0:
        max_dist = 1.0
    max_arrive = max(c[3] for c in candidates)
    if max_arrive <= 0:
        max_arrive = 1.0

    # Base cost for each candidate: distance + wait + demand usage
    base_costs = []
    for (node, demand, dist, arrive, tw_start, tw_end) in candidates:
        wait = max(0.0, tw_start - arrive)
        # Cost components: distance, waiting time, demand ratio
        dist_cost = dist / max_dist
        wait_cost = wait / max(max_arrive, 1.0)
        cap_cost = demand / rest_capacity if rest_capacity > 0 else 1.0
        # Weighted base cost
        w_dist = 0.5
        w_wait = 0.3
        w_cap = 0.2
        base_costs.append(w_dist * dist_cost + w_wait * wait_cost + w_cap * cap_cost)

    base_costs = np.array(base_costs)

    # Regret: for each candidate i, compute the cost increase if we skip i
    # 2-step regret: min cost among other candidates minus cost of candidate i
    regret = np.zeros(len(candidates))
    for i in range(len(candidates)):
        if len(candidates) <= 2:
            regret[i] = 0.0
        else:
            other_costs = [base_costs[j] for j in range(len(candidates)) if j != i]
            min_other = min(other_costs)
            regret[i] = max(0.0, min_other - base_costs[i])

    # Final score: base cost - regret (higher regret means more urgent to pick now)
    regret_weight = 1.0
    final_scores = base_costs - regret_weight * regret

    best_idx = int(np.argmin(final_scores))
    return int(candidates[best_idx][0])
